function HasCloseElements(numbers: array of real; threshold: real): boolean;
begin
  var sorted := numbers.ToList;
  sorted.Sort;
  for var i := 0 to sorted.Count - 1 do
    for var j := i + 1 to sorted.Count - 1 do
      if Abs(sorted[i] - sorted[j]) < threshold then
      begin
        Result := True;
        exit;
      end;
  Result := False;
end;

begin
end.




function SeparateParenGroups(parenString: string): array of string;
begin
  var stack := new Stack<string>;
  var current := new StringBuilder;
  var resultList := new List<string>;
  var ignoreSpace := True;

  for var i := 1 to parenString.Length do
  begin
    var ch := parenString[i];

    if ignoreSpace then
    begin
      if ch <> ' ' then
      begin
        current.Append(ch);
        ignoreSpace := False;
      end;
      continue;
    end;

    if ch = '(' then
    begin
      if current.Length > 0 then
      begin
        resultList.Add(current.ToString);
        current.Clear;
      end;
      stack.Push('(');
    end
    else if ch = ')' then
    begin
      if stack.Count > 0 then
      begin
        current.Append(ch);
        stack.Pop;

        if stack.Count = 0 then
          resultList.Add(current.ToString)
        else
          current.Clear;
      end
      else
        raise new System.FormatException('Mismatched parentheses');
    end
    else
      raise new System.ArgumentException('Invalid character');
  end;

  Result := resultList.ToArray;
end;

begin
end.




