function ParseNestedParens(parenString: string): array of integer;
begin
  var stack := new Stack<integer>;
  var counts := new List<integer>;
  var currentCount := 0;
  foreach var ch in parenString do
  begin
    if ch = '(' then
    begin
      stack.Push(currentCount);
      currentCount := 0;
    end
    else if ch = ')' then
    begin
      currentCount := currentCount + stack.Pop + 1;
      counts.Add(currentCount);
    end;
  end;
  Result := counts.ToArray;
end;

