function MakePalindrome(str: string): string;
begin
  var n := str.Length;
  if n = 0 then
  begin
    Result := '';
    exit;
  end;

  // Find longest palindrome suffix
  var reversed := ReverseString(str);
  var best := 1;
  var start := 1;
  for var i := 2 to n do
  begin
    var len := best;
    while (reversed[i - best + 1] = str[best + 1]) and (best < n - i + 1) do
    begin
      best += 1;
      len += 1;
    end;
    if len > best then
    begin
      best := len;
      start := i - best;
    end;
  end;

  // Return palindrome
  Result := str.Substring(start - 1, best);
end;

begin
end.




function StringXor(a, b: string): string;
begin
  var maxLen := Max(a.Length, b.Length);
  var res := new StringBuilder;
  var carry := 0;

  for var i := maxLen - 1 downto 0 do
  begin
    var aBit := if i < a.Length then StrToInt(a[a.Length - 1 - i]) else 0;
    var bBit := if i < b.Length then StrToInt(b[b.Length - 1 - i]) else 0;
    var xorBit := (aBit xor bBit) + carry;
    carry := aBit and bBit;
    res.Append(xorBit.ToString);
  end;

  if carry <> 0 then
    res.Insert(0, '1');

  Result := res.ToString;
end;

begin
end.




