function FindClosestElements(numbers: array of real): (real, real);
begin
  var sortedNumbers := numbers.ToList;
  sortedNumbers.Sort;
  var length := sortedNumbers.Count;
  var minDiff := Abs(sortedNumbers[1] - sortedNumbers[0]);
  var res := (sortedNumbers[0], sortedNumbers[1]);

  for var i := 2 to length - 1 do
  begin
    var diff := Abs(sortedNumbers[i] - sortedNumbers[i-1]);
    if diff < minDiff then
    begin
      minDiff := diff;
      res := (sortedNumbers[i-1], sortedNumbers[i]);
    end;
  end;

  Result := res;
end;

begin
end.




