function Poly(xs : array of real; x : real): real;
{ Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n }
begin
  var _result := 0.0;
  for var i := 0 to xs.Length - 1 do
    _result := _result + xs[i] * Power(x, i);
  Result := _result;
end;
function FindZero(xs: array of real): real;
begin
  var n := xs.Length;
  if n = 0 then
  begin
    Result := real.PositiveInfinity;
    exit;
  end;
  if n mod 2 <> 0 then
  begin
    Result := real.NegativeInfinity;
    exit;
  end;
  var a := new real[n];
  for var i := 0 to n - 1 do
    a[i] := xs[i];
  var b := new real[n + 1];
  for var i := 0 to n do
    b[i] := 0;
  b[n] := 1;
  var eps := 1e-10;
  while true do
  begin
    var cond := 0.0;
    for var i := 0 to n - 1 do
      cond := cond + Abs(a[i]);
    for var i := 0 to n do
      b[i] := b[i] + Abs(a[i]) * Abs(b[i + 1]);
    for var i := 0 to n do
      a[i] := b[i] - Abs(a[i]) * b[i + 1];
    for var i := 0 to n - 1 do
      cond := cond + Abs(a[i]);
    cond := cond + eps;
    if cond < eps then break;
    var flag := false;
    for var i := 0 to n - 1 do
      if Abs(a[i]) > eps then
      begin
        flag := true;
        break;
      end;
    if not flag then
    begin
      Result := real.NegativeInfinity;
      exit;
    end;
    var m := n;
    var p := new real[n + 1];
    for var i := 0 to n do
      p[i] := b[i];
    var q := new real[n + 1];
    for var i := 0 to n do
      q[i] := a[i];
    var r := new real[n + 1];
    for var i := 0 to n do
      r[i] := p[i] - q[i] * p[i + 1];
    var s := new real[n + 1];
    for var i := 0 to n do
      s[i] := r[i] / (1.0 + q[i] * q[i]);
    var t := new real[n + 1];
    for var i := 0 to n do
      t[i] := r[i] - s[i] * q[i];
    for var i := n downto 1 do
      p[i] := p[i] - s[i] * p[i + 1];
    for var i := 0 to n - 1 do
      if Abs(t[i]) > Abs(p[i + 1]) then
      begin
        m := i;
        break;
      end;
    var x := 0.0;
    for var i := 0 to m do
      x := x + a[i] * Power(x, i);
    Result := x;
  end;
end;

begin
end.




