function TriplesSumToZero(lst: array of integer): boolean;
begin
  var sorted := lst.ToList;
  sorted.Sort;

  for var i := 0 to sorted.Count - 3 do
  begin
    if (i > 0) and (sorted[i] = sorted[i - 1]) then
      continue;

    var left := i + 1;
    var right := sorted.Count - 1;

    while left < right do
    begin
      var sum := sorted[i] + sorted[left] + sorted[right];
      if sum = 0 then
      begin
        Result := True;
        exit;
      end
      else if sum < 0 then
        left += 1
      else
        right -= 1;
    end;
  end;

  Result := False;
end;

begin
end.




