function StrangeSortList(lst: array of integer): array of integer;
begin
  if lst.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var sorted := lst.ToArray;
  var reversed := false;

  while True do
  begin
    if reversed then
    begin
      sorted := sorted.OrderByDescending(x -> x).ToArray;
      reversed := false;
    end
    else
    begin
      sorted := sorted.OrderBy(x -> x).ToArray;
      reversed := true;
    end;

    var resultList := new List<integer>;
    var maxVal := sorted.Max;
    var minVal := sorted.Min;

    // First part: add min and max
    resultList.Add(minVal);
    resultList.Add(maxVal);

    // Remove min and max from sorted
    sorted := sorted.Where(x -> x <> minVal || x <> maxVal).ToArray;

    if sorted.Length = 0 then
      break;

    // Second part: add remaining sorted elements
    resultList.AddRange(sorted);

    Result := resultList.ToArray;
  end;
end;

begin
end.




