function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var res := 0;
  var bucket := new integer[capacity + 1];

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i][j] = 1 then
        bucket[j] := bucket[j] + 1;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i][j] = 0 then
      begin
        var need := bucket[j];
        var left := bucket[j + 1];
        var move := Min(need, left);
        bucket[j] := bucket[j] - move;
        bucket[j + 1] := bucket[j + 1] + move;
        res := res + move;
      end;

  Result := res;
end;

begin
end.




