function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  if (n = 0) or (k = 0) then
  begin
    Result := new integer[0];
    exit;
  end;

  var visited := new boolean[n, n, k + 1];
  var queue := new Queue<(integer, integer, integer)>;
  queue.Enqueue((0, 0, 0));

  while queue.Count > 0 do
  begin
    var (x, y, z) := queue.Dequeue;
    if (z = k) and ((x = 0) or (y = 0) or (x = n - 1) or (y = n - 1)) then
    begin
      Result := new integer[k];
      var idx := 0;
      var cur := (x, y, z);
      while cur[2] > 0 do
      begin
        Result[idx] := grid[cur[0]][cur[1]];
        idx += 1;
        cur := (cur[0] + cur[2], cur[1] + cur[3], cur[2] - 1);
      end;
      Result[idx] := grid[cur[0]][cur[1]];
      exit;
    end;

    var dx := |0, 0, 1, -1|;
    var dy := |1, -1, 0, 0|;

    for var i := 0 to 3 do
    begin
      var nx := cur[0] + dx[i];
      var ny := cur[1] + dy[i];
      if (nx >= 0) and (nx < n) and (ny >= 0) and (ny < n) and not visited[nx, ny, cur[2]] then
      begin
        visited[nx, ny, cur[2]] := True;
        queue.Enqueue((nx, ny, cur[2] + 1));
      end;
    end;
  end;

  Result := new integer[0];
end;

begin
end.




