    else
      trib.Add((n - 1) / 2 + (n - 2) / 2 + (n + 1) / 2);
  end;

  for var i := trib.Count to n do
  begin
    var t := trib[i - 1] + trib[i - 2] + trib[i - 3];
    trib.Add(t);
  end;

  Result := trib.ToArray;
end;

